local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
   Name = "CatPat ui",
   Icon = 0,
   LoadingTitle = "CatPat UI",
   LoadingSubtitle = "by CatPat",
   Theme = "Ocean - Ocean", 

   DisableRayfieldPrompts = false,
   DisableBuildWarnings = false, 
   ConfigurationSaving = {
      Enabled = true,
      FolderName = nil,
      FileName = "CatPat ui"
   },

   Discord = {
      Enabled = false,
      Invite = "noinvitelink", 
      RememberJoins = true 
   },

   KeySystem = true,
   KeySettings = {
      Title = "CatPat ui",
      Subtitle = "Key System",
      Note = "key is haker", 
      FileName = "Key",
      SaveKey = true, 
      GrabKeyFromSite = false, 
      Key = {"haker"}
   }
})

local MainTab = Window:CreateTab("Home", nil)
local MainSection = MainTab:CreateSection("Main")

Rayfield:Notify({
   Title = "🤓 welcome to CatPat's UI",
   Content = "Sigma",
   Duration = 10,
   Image = nil,
})

local Button = MainTab:CreateButton({
   Name = "fe script",
   Callback = function()
   loadstring(game:HttpGet('https://raw.githubusercontent.com/EdgeIY/infiniteyield/master/source'))()
   end,
})

local Slider = MainTab:CreateSlider({
   Name = "walkSpeed Slider",
   Range = {0, 300},
   Increment = 1,
   Suffix = "Speed",
   CurrentValue = 16,
   Flag = "Slider1",
   Callback = function(Value)
        game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = (Value)
   end, 
})

local Tab = Window:CreateTab("Fe scripts", nil) 
local Section = Tab:CreateSection("Cool scripts")

local Button = Tab :CreateButton({
